<div class="page-heading"><div><a class="back-link" href="<?= site_url('petugas/master') ?>">← Master data</a><div class="eyebrow">Hak akses</div><h1>Master peran</h1><p>Peran sistem memiliki kode akses tetap. Ubah nama dan keterangan, atau atur ketersediaannya untuk akun baru.</p></div><?php if ($this->metro->has_role($current_user->id,array('administrator'))): ?><a class="button primary" href="<?= site_url('petugas/hak-akses') ?>">Atur hak akses</a><?php endif; ?></div>
<section class="card table-card"><div class="filter-results"><span><strong><?= (int)$pagination['total'] ?></strong> peran sistem</span><small>Peran inti Superadmin dan Pemohon harus tetap aktif.</small></div><?php if ($rows): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Kode</th><th>Nama peran</th><th>Keterangan</th><th>Urutan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $row): $core=in_array($row->role_code,array('administrator','applicant'),TRUE); ?><tr><td data-label="Kode"><strong><?= e($row->role_code) ?></strong></td><td data-label="Nama"><strong><?= e($row->role_name) ?></strong></td><td data-label="Keterangan"><?= e($row->description ?: '—') ?></td><td data-label="Urutan"><?= (int)$row->sort_order ?></td><td data-label="Status"><span class="badge <?= $row->is_active?'success':'danger' ?>"><?= $row->is_active?'Aktif':'Nonaktif' ?></span></td><td data-label="Aksi"><div class="row-actions"><button type="button" class="action-link" data-modal-open="edit-role-<?= (int)$row->id ?>">Edit</button><?php if (!$core): ?><form method="post" action="<?= site_url('petugas/master/status/peran/'.$row->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="action-link" type="submit"><?= $row->is_active?'Nonaktifkan':'Aktifkan' ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="table-empty">Belum ada peran sistem.</div><?php endif; ?><?= metro_pager($pagination,'petugas/master/peran') ?></section>
<?php foreach ($rows as $row): ?><dialog id="edit-role-<?= (int)$row->id ?>" class="admin-modal" aria-labelledby="edit-role-title-<?= (int)$row->id ?>"><div class="modal-head"><div><small><?= e($row->role_code) ?></small><h2 id="edit-role-title-<?= (int)$row->id ?>">Edit peran</h2></div><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button></div><form method="post" action="<?= site_url('petugas/master/peran') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><input type="hidden" name="id" value="<?= (int)$row->id ?>"><div class="modal-body"><div class="form-grid"><label>Kode<input value="<?= e($row->role_code) ?>" disabled></label><label>Nama peran<input name="role_name" required maxlength="100" value="<?= e($row->role_name) ?>"></label><label>Urutan<input type="number" name="sort_order" min="0" value="<?= (int)$row->sort_order ?>"></label><label class="span-2">Deskripsi<input name="description" maxlength="255" value="<?= e($row->description) ?>"></label></div><?php if (!in_array($row->role_code,array('administrator','applicant'),TRUE)): ?><label class="master-check"><input type="checkbox" name="is_active" value="1"<?= $row->is_active?' checked':'' ?>> Aktif untuk akun baru</label><?php endif; ?></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button primary" type="submit">Simpan perubahan</button></div></form></dialog><?php endforeach; ?>
